WITH filtered AS (SELECT *, CONCAT(channel, ', ', promo_code) AS channel_promo_code, CONCAT_WS('-', promo_code, channel) AS promo_code_channel_key FROM promotions WHERE starts_on >= TO_DATE('2024-04-08')) SELECT promo_code, APPROX_PERCENTILE(discount_pct, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_quartiles, COUNT(*) FILTER (WHERE promo_code = 'WELCOME5') AS welcome5_rows, COUNT_IF(channel = 'store') AS store_events, MAX(discount_pct) FILTER (WHERE channel = 'mobile') AS mobile_max_discount_pct FROM filtered GROUP BY promo_code;
